/**
 * @summary Search Bible verses
 */
export const getSearchBibleUrl = (params: SearchBibleParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/bible/search?${stringifiedParams}`
    : `/api/bible/search`;
};

export const searchBible = async (
  params: SearchBibleParams,
  options?: RequestInit,
): Promise<BibleVerse[]> => {
  return customFetch<BibleVerse[]>(getSearchBibleUrl(params), {
    ...options,
    method: "GET",
  });
};

